#include <stdio.h>
#include <stdbool.h>

int main(void)
{
    int num1, num2; // Declare two integer variables

    // Prompt user for the first number and read it
    printf("Enter the first integer: ");
    scanf("%i", &num1);

    // Prompt user for the second number and read it
    printf("Enter the second integer: ");
    scanf("%i", &num2);

    // Calculate and print the sum
    printf("Sum: %i\n", num1 + num2);

    // Calculate and print the difference
    printf("Difference: %i\n", num1 - num2);

    // Calculate and print the product
    printf("Product: %i\n", num1 * num2);

    // Handle division-by-zero safety for remainder and quotient
    if (num2 == 0)
    {
        printf("Remainder: undefined (division by zero)\n");
        printf("Quotient: undefined (division by zero)\n");
    }
    else
    {
        // Remainder (modulo) for integers
        printf("Remainder: %i\n", num1 % num2);

        // Floating-point quotient using type casting so we don't lose fractional part
        printf("Quotient: %.2f\n", (float)num1 / num2);
    }

    return 0;
}

#include <stdio.h>

int main(void)
{
    double a, b;
    printf("Enter the first number: ");
    scanf("%lf", &a);
    printf("Enter the second number: ");
    scanf("%lf", &b);

    printf("Sum: %.2f\n", a + b);
    printf("Difference: %.2f\n", a - b);
    printf("Product: %.2f\n", a * b);

    if (b == 0.0)
    {
        printf("Quotient: undefined (division by zero)\n");
        printf("Remainder: undefined (not applicable for floats)\n");
    }
    else
    {
        printf("Quotient: %.2f\n", a / b);
        printf("Remainder: undefined (not applicable for floats)\n");
    }

    return 0;
}

